import{_ as a,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"05 | K8s最小部署资源对象Pod","description":"","frontmatter":{},"headers":[{"level":2,"title":"认识 Pod","slug":"认识-pod","link":"#认识-pod","children":[{"level":3,"title":"共享网络","slug":"共享网络","link":"#共享网络","children":[]},{"level":3,"title":"共享存储","slug":"共享存储","link":"#共享存储","children":[]},{"level":3,"title":"部署一个多容器的 Pod","slug":"部署一个多容器的-pod","link":"#部署一个多容器的-pod","children":[]}]},{"level":2,"title":"使用 kubectl 命令管理 Pod","slug":"使用-kubectl-命令管理-pod","link":"#使用-kubectl-命令管理-pod","children":[{"level":3,"title":"创建 Pod","slug":"创建-pod","link":"#创建-pod","children":[]},{"level":3,"title":"查看 Pod","slug":"查看-pod","link":"#查看-pod","children":[]},{"level":3,"title":"其他命令","slug":"其他命令","link":"#其他命令","children":[]}]},{"level":2,"title":"静态 Pod","slug":"静态-pod","link":"#静态-pod","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"零基础拿下云原生CKA认证/05｜K8s最小部署资源对象Pod.md","filePath":"零基础拿下云原生CKA认证/05｜K8s最小部署资源对象Pod.md","lastUpdated":1795561650000}'),p={name:"零基础拿下云原生CKA认证/05｜K8s最小部署资源对象Pod.md"};function t(l,s,o,d,h,k){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_05-k8s最小部署资源对象pod" tabindex="-1">05 | K8s最小部署资源对象Pod <a class="header-anchor" href="#_05-k8s最小部署资源对象pod" aria-label="Permalink to &quot;05 | K8s最小部署资源对象Pod&quot;">​</a></h1><p>你好，我是雪飞。</p><p>上一课我们学习了 YAML 文件的相关知识，同时动手编写了 YAML 文件，现在你就可以使用YAML 文件来与 K8s 集群沟通，从而实现应用部署和集群管理的需求。在接下来的课程中，我将继续深入介绍 K8s 中常用的资源对象，这些资源对象提供了应用部署、参数配置、网络访问、持久化存储、安全策略等等功能，满足各种实际的应用场景。对于 K8s 资源对象的管理，我会同时使用 kubectl 命令和 YAML 文件这两种方式来加深你的理解和记忆。</p><p>今天，我给你讲一下 K8s 中最核心的资源对象——Pod，它是 K8s 管理的最小可部署资源对象。其他很多资源对象都是基于 Pod 来实现更复杂的应用部署和管理。例如，Deployment 就是通过管理多个 Pod 来实现应用的高可用性和滚动更新。接下来，让我们详细了解一下什么是 Pod。</p><h2 id="认识-pod" tabindex="-1">认识 Pod <a class="header-anchor" href="#认识-pod" aria-label="Permalink to &quot;认识 Pod&quot;">​</a></h2><p>Pod 的中文意思为豌豆荚，因为 Pod 中包含了一个或多个容器，容器和 Pod 的关系很像豌豆和豆荚的关系，所以这就是 Pod 名称的来历。在 K8s 中，Pod 是一个逻辑概念，而容器才是运行着应用镜像的实际载体，那为啥 K8s 不直接管理容器，而是还要搞出一个 Pod 呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/1.png" alt=""></a></p><p>最重要的原因就是：在一些常见的应用场景下，容器并不是孤零零的存在，它可能会跟其他容器之间有着很亲密的关系，它们相互协作，一起启动，一起停止，一起提供服务，同时它们需要彼此间可以方便的通信以及访问相同的数据。所以 K8s 就在容器的基础上创建了 Pod 这个更高层级的资源对象，Pod 可以将多个容器组合到一起部署和管理，同一 Pod 中的容器可以共享网络和存储空间，这种机制保证了对容器管理的一致性和灵活性。</p><p>举个具体例子， Pod 中多容器常用于边车模式（Sidecar），这种模式包含主容器和辅助容器，主容器运行核心业务应用，而辅助容器则负责日志收集、监控等任务，在不影响主业务的情况下扩展了应用功能。这种关系类似三轮摩托车，在摩托车的一侧加装一个边车来增加额外的空间，所以被叫做边车模式。此外，新一代 Service Mesh（服务网格）技术也利用了这种边车模式来增强服务间的通信和管理能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/2.png" alt=""></a></p><p>在实际应用中，Pod 可以包含一个容器也可以包含多个容器，非常灵活。对于多个容器，Pod实现了容器间共享网络和存储空间的机制，下面我们来看下 Pod 是如何实现这两种机制。</p><h3 id="共享网络" tabindex="-1">共享网络 <a class="header-anchor" href="#共享网络" aria-label="Permalink to &quot;共享网络&quot;">​</a></h3><p>首先，让我们讨论一下 Pod 中容器共享网络的机制。K8s 使用了一种简单的方式来实现共享网络，那就是在 Pod 中的容器启动之前，先自动运行一个 Infra Container（基础容器），这个容器运行了一个非常小的镜像，大概几百 KB，是一个 C 语言写的永远处于 pause（暂停）状态的容器，又叫 pause 容器。然后，当 Pod 中的其他容器启动时，它们都会加入到 InfraContainer 的网络中，从而使用 Infra Container 的网络中的网络设备、IP 地址等网络相关的信息，这样就实现了容器之间共享网络。这有点像是一个电脑上同时有两个网络应用，它们都是用这个电脑的同一块网卡来处理网络请求，所以通过 localhost 也就能相互访问。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/3.png" alt=""></a></p><h3 id="共享存储" tabindex="-1">共享存储 <a class="header-anchor" href="#共享存储" aria-label="Permalink to &quot;共享存储&quot;">​</a></h3><p>接下来，我们再看一下 Pod 中多个容器共享存储，Pod 是通过多个容器挂载共同的数据卷Volume（数据卷）来实现共享存储的。你可以把数据卷想象成一个共享网盘，Pod 中的容器都可以通过它来存取文件。例如之前说到的边车模式，主容器可以将日志文件写到共享存储空间，然后边车容器可以直接读取共享存储空间的文件来获取日志信息，从而实现业务功能和统计分析功能的分离，就像两个同事共用一个文件夹一样方便。这样，不仅能让各个容器各司其职，还能让整个系统更加灵活和易于管理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/05/4.png" alt=""></a></p><h3 id="部署一个多容器的-pod" tabindex="-1">部署一个多容器的 Pod <a class="header-anchor" href="#部署一个多容器的-pod" aria-label="Permalink to &quot;部署一个多容器的 Pod&quot;">​</a></h3><p>了解了 Pod 的共享原理，下面我们就动手部署一个多容器的 Pod，来验证一下容器间的共享网络和共享存储。部署多容器的 Pod 是 CKA 考试的核心考点，考试中需要用 YAML 文件的方式部署 Pod，所以你要了解这个 YAML 文件的写法。</p><p>首先，编写一个包含两个容器的 Pod 的 YAML 文件（two_container_pod.yaml），其中一个是Web 服务应用 Nginx，另一个是 Busybox。Busybox 是一个工具镜像，其中包含了 Linux 系统命令行工具，在 Busybox 容器启动的时候执行了一条 sleep 休眠命令，用于保持容器持续运行。</p><p>注意：课程中的例子我都放到了公开的 GitHub 仓库中供你参考，你可以使用 Git 工具把仓库拉到本地查看示例。</p><p>我在 Pod 的 spec 属性里创建了一个名为 data 的本地临时 Volume（数据卷类型是emptyDir），同时在 Pod 的每个容器中都挂载了这个 Volume。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># two_container_pod.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Pod</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: test</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> containers:</span></span>
<span class="line"><span> - image: nginx</span></span>
<span class="line"><span>   name: nginx</span></span>
<span class="line"><span>   volumeMounts:   # 容器 Nginx 挂载 Volume</span></span>
<span class="line"><span>   - name: data</span></span>
<span class="line"><span>     mountPath: /data</span></span>
<span class="line"><span> - image: busybox</span></span>
<span class="line"><span>   name: busybox</span></span>
<span class="line"><span>   command: [&quot;/bin/sh&quot;,&quot;-c&quot;,&quot;sleep 3600&quot;]</span></span>
<span class="line"><span>   volumeMounts:   # 容器 Busybox 挂载 Volume</span></span>
<span class="line"><span>   - name: data</span></span>
<span class="line"><span>     mountPath: /data</span></span>
<span class="line"><span> volumes:          # 定义了一个临时 Volume</span></span>
<span class="line"><span> - name: data</span></span>
<span class="line"><span>   emptyDir: {}</span></span></code></pre></div><p>然后运行以下命令部署 YAML 文件，等待 Pod 运行成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl apply -f two_container_pod.yaml</span></span>
<span class="line"><span>pod/test created</span></span></code></pre></div><p>通过 “kubectl get pod -o wide” 命令，可以查看 Pod 部署的详细列表信息。此时，可以看到Pod 已经成功部署到了 k8s-worker1 节点上。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get pod -o wide</span></span>
<span class="line"><span>NAME  READY  STATUS    RESTARTS   AGE   IP              NODE          NOMINATED N</span></span>
<span class="line"><span>test  2/2    Running   0          92s   10.244.194.68   k8s-worker1   &lt;​none&gt;</span></span></code></pre></div><ol><li>验证共享网络</li></ol><p>我们远程登录到 k8s-worker1 节点上，并使用 “docker ps” 命令查看节点上正在运行的容器。通过这种方式，我们可以确认在 k8s-worker1 节点上运行着 pause 容器，也就是提供共享网络的 Infra Container。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-worker1 ~]# docker ps | grep test</span></span>
<span class="line"><span>aab5e75d353f   busybox                                              &quot;/bin/sh -c &#39;</span></span>
<span class="line"><span>87a6c4de517d   nginx                                                &quot;/docker-entr</span></span>
<span class="line"><span>438f772319e5   registry.aliyuncs.com/google_containers/pause:3.9    &quot;/pause&quot;</span></span></code></pre></div><p>回到 Master 节点上，我们使用 “kubectl exec -it” 命令进入 Busybox 容器内部。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> busybox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span></span></code></pre></div><ul><li><p>-it：表示使用终端应用作为访问容器的标准输入。</p></li><li><p>-c：表示要进入的容器名称，如果 Pod 里只有一个容器，就不需要这个参数。</p></li><li><p>-- sh：表示进入容器之后打开 shell 终端应用。</p></li></ul><p>Nginx 容器部署成功后，就会启动了一个 Web 服务，访问 Nginx 容器的 80 端口，就可以访问到它的默认 “index.html” 文件。所以我们在 Busybox 容器的终端应用中，使用 wget 命令来请求本地网络地址 Localhost 的 80 端口，这个命令通常用来远程获取文件，可以看到 wget 命令获取到了 Nginx 容器的 80 端口返回的 “index.html” 文件，这证明了两个容器共享同一个网络空间，并且可以通过 Localhost 地址互相通信。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl exec -it test -c busybox -- sh</span></span>
<span class="line"><span>/ # wget localhost:80</span></span>
<span class="line"><span>Connecting to localhost:80 (127.0.0.1:80)</span></span>
<span class="line"><span>saving to &#39;index.html&#39;</span></span>
<span class="line"><span>index.html    100% |****************************|   615  0:00:00 ETA</span></span>
<span class="line"><span>&#39;index.html&#39; saved</span></span></code></pre></div><ol start="2"><li>验证共享存储</li></ol><p>我们继续在 Busybox 容器内，进入到 “/data” 目录，这个就是容器挂载数据卷的目录，在这个目录内创建一个内容为 “Hello, I am Busybox” 的文本文件（hello.txt）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ # cd /data</span></span>
<span class="line"><span>/ # echo &quot;Hello, I am Busybox&quot; &gt; hello.txt</span></span></code></pre></div><p>然后退出 Busybox 容器。只需输入 exit 命令，就可以回到集群 Master 节点的终端。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ # exit</span></span>
<span class="line"><span>[root@k8s-master ~]#</span></span></code></pre></div><p>这时，我们已经在共享存储空间中创建了一个文件，现在就要去 Nginx 容器中去看看是否能找到这个文件。使用 “kubectl exec -it” 命令进入到 Nginx 容器内部，然后通过 “cat” 命令直接查看 “/data/hello.txt” 文件内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl exec -it test -c nginx -- sh</span></span>
<span class="line"><span>/ # cat /data/hello.txt</span></span>
<span class="line"><span>Hello, I am Busybox</span></span></code></pre></div><p>此时可以看到，在 Nginx 容器挂载的 “/data” 目录下，已经可以读取到在 Busybox 容器中创建的 “/data/hello.txt” 文件内容了。这证明了同一个 Pod 下的多个容器通过挂载相同的数据卷Volume 实现了共享存储空间。</p><h2 id="使用-kubectl-命令管理-pod" tabindex="-1">使用 kubectl 命令管理 Pod <a class="header-anchor" href="#使用-kubectl-命令管理-pod" aria-label="Permalink to &quot;使用 kubectl 命令管理 Pod&quot;">​</a></h2><p>刚才我们用 YAML 文件的方式来创建了多容器的 Pod，然而通过 kubectl 命令是不能直接创建多容器的 Pod，它只能创建单容器的简单 Pod，所以我们也可以看出使用 kubectl 命令与YAML 文件的一个区别，YAML 文件更适合实现复杂的部署要求。</p><p>现在我们就来学习如何使用 Kubectl 命令来管理 Pod。</p><h3 id="创建-pod" tabindex="-1">创建 Pod <a class="header-anchor" href="#创建-pod" aria-label="Permalink to &quot;创建 Pod&quot;">​</a></h3><p>使用 “kubectl run” 命令可以快速创建一个简单的 Pod，命令后面可以根据不同的容器镜像应用类型而增加不同参数。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​pod名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --image=nginx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--port=80]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​pod名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --image=busybox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-- </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sleep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3600]</span></span></code></pre></div><ul><li><p>&lt;​pod 名称 &gt;：这是新创建的 Pod 的名称。</p></li><li><p>–image=nginx：指定 Pod 使用的容器镜像是 nginx。</p></li><li><p>–port=80：设置容器暴露的端口为 80，对于 Web 类型应用，外部请求会通过该端口号访问到容器。如果不需要端口访问，也可以不用该参数。</p></li><li><p>– sleep 3600：–参数可以指定容器启动时要执行的命令，这里是执行 “sleep 3600” 命令，也就是让 Busybox 容器保持运行 3600 秒。如果容器启动时不需要执行命令，也可以不用该参数。</p></li></ul><h3 id="查看-pod" tabindex="-1">查看 Pod <a class="header-anchor" href="#查看-pod" aria-label="Permalink to &quot;查看 Pod&quot;">​</a></h3><p>使用 “kubectl get pod” 命令可以查看 Pod 列表信息，由于 Pod 的缩写（SHORTNAMES）是po，也可以在命令中使用 po 代替 pod。命令后面可以根据需要增加不同参数。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-o </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wide]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​namespace名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​pod名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-o </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yaml]</span></span></code></pre></div><ul><li><p>-o wide：用来查看到更多的 Pod 信息，例如 Pod 的 IP 地址、部署所在节点等等。</p></li><li><p>-n &lt;​namespace 名称 &gt;：-n 参数可以指定命名空间名称，命名空间是对资源对象的一种逻辑分组隔离方式，Pod 可以创建到不同的命名空间下，这时就需要增加 -n 参数来指定 Pod所在的命名空间，不加 -n 参数则是查看默认命名空间（default）下的 Pod。</p></li><li><p>-o yaml：用来以 YAML 文件的方式查看指定的 Pod。</p></li></ul><p>使用 “kubectl describe pod” 命令可以查看 Pod 的详细信息。如果 Pod 不在默认命名空间，需要使用 “-n” 参数指定 Pod 所在的命名空间。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​pod名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​namespace名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>命令返回结果（返回信息太多，我用 “…” 做了省略）中看到的 Pod 信息非常丰富，包括基础信息、容器信息、状态信息、挂载存储卷信息、调度策略信息、事件信息等等。这些数据对Pod 的故障排查非常有用，后续我们也会经常使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl describe pod test</span></span>
<span class="line"><span>Name:             test</span></span>
<span class="line"><span>Namespace:        default</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>Containers:</span></span>
<span class="line"><span> nginx:</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>Conditions:</span></span>
<span class="line"><span> Type              Status</span></span>
<span class="line"><span> Initialized       True</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>Volumes:</span></span>
<span class="line"><span> data:</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>QoS Class:                   BestEffort</span></span>
<span class="line"><span>Node-Selectors:              &lt;​none&gt;</span></span>
<span class="line"><span>Tolerations:                 node.kubernetes.io/not-ready:NoExecute op=Exists for</span></span>
<span class="line"><span>                            node.kubernetes.io/unreachable:NoExecute op=Exists f</span></span>
<span class="line"><span>Events:</span></span>
<span class="line"><span> Type    Reason     Age   From               Message</span></span>
<span class="line"><span> ----    ------     ----  ----               -------</span></span>
<span class="line"><span> Normal  Scheduled  56s   default-scheduler  Successfully assigned default/test</span></span>
<span class="line"><span> Normal  Pulling    55s   kubelet            Pulling image &quot;nginx&quot;</span></span></code></pre></div><h3 id="其他命令" tabindex="-1">其他命令 <a class="header-anchor" href="#其他命令" aria-label="Permalink to &quot;其他命令&quot;">​</a></h3><p>管理 Pod 的其他命令参考以下小卡片，有些命令已经出现过很多次，相信你已经很熟悉了。如果 Pod 不在默认命名空间（default），这些命令都需要使用 “-n” 参数指定 Pod 所在的命名空间，否则会提示 Pod 没找到。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">删除 Pod：kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pod </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​pod名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">编辑 Pod，修改 YAML 文件后自动生效：kubectl edit pod </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​pod名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">进入 Pod 内部：kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​pod名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> -- sh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">查看 Pod 日志：kubectl logs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​pod名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>了解了 Pod 的共享机制和相关命令，我们对 Pod 已经有了一个全面的认识。最后我再给你讲一种特殊的 Pod —— 静态 Pod。</p><h2 id="静态-pod" tabindex="-1">静态 Pod <a class="header-anchor" href="#静态-pod" aria-label="Permalink to &quot;静态 Pod&quot;">​</a></h2><p>在 K8s 中，静态 Pod 是一种非常特殊的 Pod，它的 YAML 文件就直接存放在集群各节点的指定目录位置（“/etc/kubernetes/manifests”），静态 Pod 会自动部署，而不是通过 K8s 的 APIServer 创建。静态 Pod 通常用于部署集群级别的系统组件，如 K8s 集群自己的很多系统组件就是静态 Pod，这些组件需要在集群启动时就可用，并且可以随着节点重启而自动重启。对于静态 Pod 的任何更新都需要管理员手动修改它的 YAML 文件并重启 Pod。</p><p>创建静态 Pod 不需要使用任何命令，只需要把 Pod 的 YAML 文件放到该节点的“/etc/kubernetes/manifests” 目录下，节点的 kubelet 组件就会自动创建静态 Pod。其实集群搭建的时候我们已经部署了一些静态 Pod，我们就去看一下吧。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# cd /etc/kubernetes/manifests/</span></span>
<span class="line"><span>[root@k8s-master manifests]# ls</span></span>
<span class="line"><span>etcd.yaml  kube-apiserver.yaml  kube-controller-manager.yaml  kube-scheduler.yaml</span></span></code></pre></div><p>在管理节点上的 manifests 目录中，可以看到 etcd、kube-apiserver、kube-controller-manager、kube-scheduler 这些 K8s 组件就是以静态 Pod 的方式部署到集群 kube-system 的命名空间下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我重点介绍了 K8s 中的核心资源对象——Pod。在 K8s 中，Pod 是容器管理的基本单位，每个 Pod 可以包含一个或多个容器，这些容器通过 Infra Container（基础容器）共享网络，同时通过挂载相同的数据卷 Volume 来实现共享存储，这两种机制保证了 Pod 对容器管理的一致性和灵活性，简化了对容器的管理。</p><p>接着，我带你使用 YAML 文件的方式部署了一个包含两个容器的 Pod ，并且验证了 Pod 的共享网络和共享存储的机制。部署多容器 Pod 是 CKA 的考点，你一定要熟悉它的 YAML 文件的写法。你也需要熟悉 Pod 相关的 kubectl 命令，特别是创建 Pod 使用的 “kubectl run” 命令，以及查看 Pod 信息使用的 “kubectl get pod” 和 “kubectl describe pod” 命令。</p><p>最后，我介绍了静态 Pod。静态 Pod 是一种通过节点上指定目录（“/etc/kubernetes/manifests”）中的 YAML 文件自动部署的特殊 Pod，在集群启动时就可用，并且可以随着节点重启而自动重启，通常用于部署集群级别的系统组件，K8s 的组件就是以静态 Pod 的方式运行。创建静态 Pod 只需要把 Pod 的 YAML 文件放到该节点的指定目录下，节点的 kubelet 组件就会自动创建静态 Pod。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这就是今天的全部内容，这节课通常会有一个考点，就是给 Pod 配置多个容器，所以最后留两道练习题给你。</p><ol><li><p>创建一个 Pod，其中运行着 Nginx、Redis、Memcache 3 个容器。</p></li><li><p>在节点 k8s-worker1 中运行一个 Nginx 的静态 Pod。</p></li></ol><p>相信经过动手实践，会让你对知识的理解更加深刻。</p>`,75)])])}const g=a(p,[["render",t]]);export{r as __pageData,g as default};
